/// <summary>
/// Parent class to post the shipment
/// </summary>
abstract class METOrderShipmentConfirmation
{
    METSalesOrderShipmentLoadHeader        metSalesOrderShipmentLoadHeader;
    METOrderReference   orderNum;
    NoYesId             shipmentLevelExecution;
    DocumentStatus      documentStatus;
    boolean             onlyPostTMS;
    boolean             enablePost;
    boolean             enableTMS;
    METProcMetrics      procMetrics;


}

Method.Source:
/// <summary>
/// Construct method for the class
/// </summary>
/// <param name = "_shipmentId">ShipmentId</param>
/// <returns>METOrderShipmentConfirmation</returns>
public static METOrderShipmentConfirmation construct(MetShipmentId _shipmentId, METOrderReference   _orderNum = '', NoYesId  _shipmentLevelExecution = false, boolean _onlyPostTMS = false)
{
    METSalesOrderShipmentLoadHeader metSalesOrderShipmentLoadHeader;
    METOrderShipmentConfirmation    metOrderShipmentConfirmation;

    if (!_shipmentId)
    {
        throw error(strFmt("@SYS19306", funcName()));
    }

    select firstonly metSalesOrderShipmentLoadHeader
            where metSalesOrderShipmentLoadHeader.ShipmentId == _shipmentId;

    if (metSalesOrderShipmentLoadHeader.TransactionType == METOrderTransactionType::SalesOrder)
    {
        metOrderShipmentConfirmation = new METOrderShipmentConfirmation_SalesOrder(metSalesOrderShipmentLoadHeader, _orderNum, _shipmentLevelExecution, _onlyPostTMS);
    }
    else if (metSalesOrderShipmentLoadHeader.TransactionType == METOrderTransactionType::TransferOrder)
    {
        metOrderShipmentConfirmation = new METOrderShipmentConfirmation_TransferOrder(metSalesOrderShipmentLoadHeader, _orderNum, _shipmentLevelExecution, _onlyPostTMS);
    }

    return metOrderShipmentConfirmation;
}

/// <summary>
/// New method for class
/// </summary>
/// <param name = "_metSalesOrderShipmentLoadHeader">ShipmentId reference</param>
protected void new(METSalesOrderShipmentLoadHeader _metSalesOrderShipmentLoadHeader, METOrderReference  _orderNum = '', NoYesId  _shipmentLevelExecution = false, boolean _onlyPostTMS = false)
{
    metSalesOrderShipmentLoadHeader = _metSalesOrderShipmentLoadHeader;
    orderNum = _orderNum;
    shipmentLevelExecution = _shipmentLevelExecution;
    onlyPostTMS = _onlyPostTMS;

    enablePost = false;
    enableTMS = false;

    if (!WHSParameters::find().METDisableTMSPostingDependentTask)
    {
        if (_onlyPostTMS)
        {
            enableTMS = true;
        }
        else
        {
            enablePost = true;
        }
    }
    else
    {
        enablePost = true;
        enableTMS = true;
    }
}

/// <summary>
/// Abstract method to have business logic for post method
/// </summary>
/// <returns>boolean value</returns>
abstract boolean post()
{
}

/// <summary>
/// Is shipment completely shipped or not based on the invoice posting for the shipment
/// </summary>
/// <returns>true</returns>
public boolean isShipmentShipped()
{
    boolean ret = true;

    if (metSalesOrderShipmentLoadHeader.TransactionType == METOrderTransactionType::SalesOrder)
    {
        CustInvoiceJour                 custInvoiceJour;
        CustPackingSlipJour             custPackingSlipJour;
        METSalesOrderShipmentLoadLines  metSalesOrderShipmentLoadLines;
        METCustTable                    metCustTable = METCustTable::find(metSalesOrderShipmentLoadHeader.CustAccount);

        if (metCustTable.FinalizationDocument == METFinalizationDocument::Invoice)
        {
            select firstonly OrderNum from metSalesOrderShipmentLoadLines
            where metSalesOrderShipmentLoadLines.ShipmentId == metSalesOrderShipmentLoadHeader.ShipmentId
            notexists join custInvoiceJour
                where custInvoiceJour.METShipmentId == metSalesOrderShipmentLoadHeader.ShipmentId
                    && custInvoiceJour.SalesId == metSalesOrderShipmentLoadLines.OrderNum;

            if (metSalesOrderShipmentLoadLines.OrderNum)
            {
                ret = false;
            }
        }
        else if (metCustTable.FinalizationDocument == METFinalizationDocument::DeliveryNote)
        {
            select firstonly OrderNum from metSalesOrderShipmentLoadLines
            where metSalesOrderShipmentLoadLines.ShipmentId == metSalesOrderShipmentLoadHeader.ShipmentId
            notexists join custPackingSlipJour
                where custPackingSlipJour.METShipmentId == metSalesOrderShipmentLoadHeader.ShipmentId
                    && custPackingSlipJour.SalesId == metSalesOrderShipmentLoadLines.OrderNum;

            if (metSalesOrderShipmentLoadLines.OrderNum)
            {
                ret = false;
            }
        }
        else
        {
            ret = true;
        }
    }

    return ret;
}

/// <summary>
/// Run method to initiate business logic
/// </summary>
public void run()
{
    boolean  result = false;

    if (enablePost)
    {
        result = this.post();
    }
    else
    {
        result = true;
    }


    if (result && this.isShipmentShipped())
    {
        METSalesOrderShipmentLoadHeader::updateDocStatusInHeader(MetShipmentStatus::Shipped, documentStatus, metSalesOrderShipmentLoadHeader.ShipmentId);

        metSalesOrderShipmentLoadHeader.reread();

        if (metSalesOrderShipmentLoadHeader.LoadStatus == MetLoadStatus::Shipped)
        {
            METSalesOrderShipmentLoadHeader::processsPickupAdvice(metSalesOrderShipmentLoadHeader.LoadId);
        }
    }
    else
    {
        METSalesOrderShipmentLoadHeader::updateDocStatusInHeader(MetShipmentStatus::Loaded, documentStatus, metSalesOrderShipmentLoadHeader.ShipmentId);
    }


    metSalesOrderShipmentLoadHeader.reread();

    if (metSalesOrderShipmentLoadHeader.ShipmentStatus == MetShipmentStatus::Shipped)
    {
        if (enableTMS)
        {
            METTMSEngineExecutionMode tmpEngineExecutionMode;

            if (metSalesOrderShipmentLoadHeader.TransactionType == METOrderTransactionType::SalesOrder)
            {
                procMetrics = METProcMetricsScope::current();
                if (procMetrics)
                {
                    procMetrics.ttsBeginTrace();
                    procMetrics.startDescriptionTime(1, "TMS");
                }

                tmpEngineExecutionMode = METTMSEngineExecutionMode::SalesOrderPackingSlip;

                //CBNF019_Observability_SalesOrderShipping
                CustInvoiceJour invoiceJourObserv;

                select firstonly invoiceJourObserv
                where invoiceJourObserv.METLoadId == metSalesOrderShipmentLoadHeader.LoadId
                    && invoiceJourObserv.METShipmentId == metSalesOrderShipmentLoadHeader.ShipmentId;

                if (invoiceJourObserv.RecId != 0)
                {
                    METTelemetrySOShippingInfoEvent salesOrderShipmentEvent = METTelemetrySOShippingInfoEvent::construct();
                    salesOrderShipmentEvent.addRunTimePropertyToAppinsights(invoiceJourObserv);

                    salesOrderShipmentEvent.processEvent(METTelemetryEventNames::SOShippingEvent);
                }
                //CBNF019_Observability_SalesOrderShipping
            }
            else
            {
                tmpEngineExecutionMode = METTMSEngineExecutionMode::TransferOrderShipped;
            }

            // CB626_TMSEngineSOPackingSlip Triggers for the TMS Engine processing on SO Delivery Note Posting
            // outside the ttscommit so in case of error does not rollback the packing slip posting
            METTMSEngineOrderProccess::construct(tmpEngineExecutionMode, metSalesOrderShipmentLoadHeader, '', true).run();

            if (procMetrics)
            {
                procMetrics.incDescriptionCount(1, 1);
                procMetrics.endDescriptionTime(1);
                procMetrics.ttsCommitTrace();
                procMetrics.endTrace();
                procMetrics.incProcessedCountWithDocument(strFmt("TMS - %1", metSalesOrderShipmentLoadHeader.ShipmentId));
            }
        }
    }
    else if (metSalesOrderShipmentLoadHeader.ShipmentStatus != MetShipmentStatus::Shipped)
    {
        if (this.isShipmentNeedToReset(metSalesOrderShipmentLoadHeader))
        {
            METSalesOrderShipmentLoadHeader::updateDocStatusInHeader(MetShipmentStatus::Open, documentStatus, metSalesOrderShipmentLoadHeader.ShipmentId);
        }
    }

}

/// <summary>
/// Method to check whether shipment need to reset based on credit management
/// </summary>
/// <param name = "_metSalesOrderShipmentLoadHeader">METSalesOrderShipmentLoadHeader reference</param>
/// <returns>Boolean value</returns>
public boolean isShipmentNeedToReset(METSalesOrderShipmentLoadHeader    _metSalesOrderShipmentLoadHeader)
{
    METSalesOrderShipmentLoadLines   metSalesOrderShipmentLoadLines;
    SalesTable                       salesTable;
    boolean                          ret;

    if (_metSalesOrderShipmentLoadHeader.TransactionType == METOrderTransactionType::SalesOrder)
    {
        select firstonly1 salesTable
            where salesTable.CustAccount == _metSalesOrderShipmentLoadHeader.CustAccount &&
                 salesTable.CredManInCreditControl == NoYes::Yes
            exists join metSalesOrderShipmentLoadLines
                where metSalesOrderShipmentLoadLines.ShipmentId == _metSalesOrderShipmentLoadHeader.ShipmentId
                   && metSalesOrderShipmentLoadLines.OrderNum == salesTable.SalesId;

        ret = salesTable.RecId != 0;

    }

    return ret;
}
